```tsx
import React, { Ref, useRef } from 'react';
import {
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useState,
} from 'react';
import {
  Button,
  Dimensions,
  SectionList,
  SectionListRenderItem,
  StyleSheet,
  Text,
  View,
} from 'react-native';
import Animated, {
  Easing,
  scrollTo,
  useAnimatedRef,
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';
import { getRuntimeKind, scheduleOnUI } from 'react-native-worklets';

const { width, height } = Dimensions.get('window');

interface CircleProps {
  size: number;
  opacity: number;
  duration: number;
  startX: number;
  startY: number;
  endX: number;
  endY: number;
  startHue: number;
  endHue: number;
}

function Circle({
  size,
  opacity,
  duration,
  startX,
  startY,
  endX,
  endY,
  startHue,
  endHue,
}: CircleProps) {
  const left = useSharedValue(startX);
  const top = useSharedValue(startY);
  const hue = useSharedValue(startHue);

  useEffect(() => {
    left.value = startX;
    top.value = startY;
    hue.value = startHue;

    const config = { duration, easing: Easing.linear };

    left.value = withRepeat(withTiming(endX, config), -1, true);
    top.value = withRepeat(withTiming(endY, config), -1, true);
    hue.value = withRepeat(withTiming(endHue, config), -1, true);
  }, [duration, startX, startY, startHue, endX, endY, endHue, hue, left, top]);

  const animatedStyle = useAnimatedStyle(
    () => ({
      backgroundColor: `hsl(${hue.value},100%,50%)`,
      transform: [{ translateX: left.value }, { translateY: top.value }],
    }),
    [],
  );

  return (
    <Animated.View
      style={[
        styles.circle,
        { opacity, width: size, height: size },
        animatedStyle,
      ]}
    />
  );
}

interface BokehProps {
  count: number;
}

function Bokeh({ count }: BokehProps) {
  const circles = useMemo(
    () => Array.from({ length: count }, makeBokehCircleParams),
    [count],
  );

  return circles.map((circleProps, i) => <Circle {...circleProps} key={i} />);
}

export default function BokehExample() {
  const ref = useRef<Scrollable>(null);

  return (
    <View style={styles.container}>
      <Bokeh count={100} />
      <Animated.View
        style={[
          styles.circle,
          {
            animationName: {
              from: {
                opacity: 1,
                zIndex: 999,
                width: 200,
                height: 200,
              },
              to: {
                width: 100,
                height: 100,
                transform: [{ translateX: 200 }, { translateY: 200 }],
                backgroundColor: 'yellow',
              },
            },
            animationDuration: 1000,
            animationIterationCount: Infinity,
            animationDirection: 'alternate',
          },
        ]}
      />
      <CSSTransition />
      <View style={{ marginTop: 50 }}>
        <Button
          title="Scroll from JS"
          onPress={() => {
            ref.current?.scrollFromJS();
          }}
        />
        <Button
          title="Scroll from UI"
          onPress={() => {
            ref.current?.scrollFromUI();
          }}
        />
      </View>
      <SectionListExample animated ref={ref} />
    </View>
  );
}

const AnimatedSectionList = Animated.createAnimatedComponent(
  SectionList<number>,
);

type Scrollable = {
  scrollFromJS: () => void;
  scrollFromUI: () => void;
};

type ExampleProps = {
  animated: boolean;
  ref: Ref<Scrollable>;
};

const DATA = [...Array(100).keys()];

function getRandomOffset() {
  'worklet';
  return Math.random() * 2000;
}

const SectionListExample = ({ animated, ref }: ExampleProps) => {
  const aref = useAnimatedRef<SectionList<number>>();

  useImperativeHandle(ref, () => ({
    scrollFromJS() {
      console.log(getRuntimeKind());
      aref.current?.scrollToLocation({
        sectionIndex: Math.floor((Math.random() * DATA.length) / 10),
        itemIndex: Math.floor((Math.random() * DATA.length) / 10),
      });
    },
    scrollFromUI() {
      scheduleOnUI(() => {
        console.log(getRuntimeKind());
        scrollTo(aref, 0, getRandomOffset(), animated);
      });
    },
  }));

  const renderItem = useCallback<SectionListRenderItem<any>>(
    ({ item }) => <Text style={styles.text}>{item}</Text>,
    [],
  );

  const sections = React.useMemo(
    () =>
      Array.from({ length: 10 }, (_, i) => ({
        title: `Section ${i + 1}`,
        data: DATA.slice(i * 10, (i + 1) * 10),
      })),
    [],
  );

  return (
    <AnimatedSectionList
      ref={aref}
      renderItem={renderItem}
      style={styles.fill}
      sections={sections}
      renderSectionHeader={({ section: { title } }) => (
        <Text style={styles.header}>{title}</Text>
      )}
      stickySectionHeadersEnabled={false}
    />
  );
};

function CSSTransition() {
  const [state, setState] = useState(false);

  useEffect(() => {
    const interval = setInterval(() => {
      setState(prev => !prev);
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  return (
    <Animated.View
      style={[
        styles.circle,
        {
          bottom: state ? 0 : 100,
          width: 100,
          height: 100,
          backgroundColor: 'red',
        },
      ]}
    />
  );
}

function randBetween(min: number, max: number) {
  return min + Math.random() * (max - min);
}

function makeBokehCircleParams(): CircleProps {
  const power = randBetween(0, 1);
  const size = 100 + power * 250;
  const opacity = 0.1 + (1 - power) * 0.1;

  const duration = randBetween(2000, 3000);

  const startX = randBetween(0, width) - size / 2;
  const startY = randBetween(0, height) - size / 2;

  const endX = startX + randBetween(-100, 100);
  const endY = startY + randBetween(-100, 100);

  const startHue = randBetween(0, 360);
  const endHue = randBetween(0, 360);

  return {
    size,
    opacity,
    duration,
    startX,
    startY,
    endX,
    endY,
    startHue,
    endHue,
  };
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: 'black',
    overflow: 'hidden',
  },
  circle: {
    position: 'absolute',
    borderRadius: 999,
  },
  fill: {
    flex: 1,
    width: '100%',
  },
  text: {
    fontSize: 50,
    textAlign: 'center',
  },
  header: {
    fontSize: 32,
    fontWeight: 'bold',
    textAlign: 'center',
  },
});
